questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
col(v) := matrix([v[1]],[v[2]]);
/* Design: resultant displacement of a multi-leg walk, with a resultant column. Names are a column of the list (one per entry). Source: adapted from SMP GCSE Foundation 1, Chapter 29, Section A, A10 (distance and compass direction on a grid map). */
legs: [[["south",600],["east",600],["west",500],["north",100]],[["east",900],["north",600],["west",200]],[["south",500],["north",300],["east",100]],[["east",900],["north",300],["south",600]],[["west",400],["east",100],["south",400]],[["north",200],["east",800],["south",600]],[["south",500],["north",800],["west",100],["east",800]],[["east",200],["north",100],["south",200],["west",800]],[["east",800],["south",200],["north",600],["west",500]],[["west",700],["south",700],["east",500]]];
ix: 1+rand(10);
LG: legs[ix]; nl: length(LG);
/* direction code: 1 east, 2 west, 3 north, 4 south */
dc(s) := if s="east" then 1 elseif s="west" then 2 elseif s="north" then 3 else 4;
uv: [[1,0],[-1,0],[0,1],[0,-1]];
/* padded to four legs (a missing fourth leg is 0 m east) */
dd: append(makelist(dc(LG[j][1]), j, 1, nl), makelist(1, j, 1, 4-nl)); ln: append(makelist(LG[j][2], j, 1, nl), makelist(0, j, 1, 4-nl));
r: lsum(ln[j]*uv[dd[j]], j, [1,2,3,4]);
pos: [lsum(if dd[j] <= 2 then ln[j] else 0, j, [1,2,3,4]), lsum(if dd[j] >= 3 then ln[j] else 0, j, [1,2,3,4])];
D: lsum(ln[j], j, [1,2,3,4]);
tr: col(r); tpos: col(pos); tswp: col([r[2],r[1]]); tneg: col(-r);
rw: tr+matrix([100],[0]); gw: abs(r[1])+abs(r[2]); D1: D+100;
badm: matrix([q],[1]);
